from __future__ import annotations


def render_drinking_report_page() -> str:
    return r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="referrer" content="no-referrer"><title>饮酒报备</title><style>
:root{font-family:system-ui,-apple-system,"Segoe UI","Microsoft YaHei",sans-serif;color:#17212b;background:#f3f6fb}*{box-sizing:border-box}body{margin:0;padding:20px 12px 32px;background:linear-gradient(180deg,#edf4ff 0,#f7f9fc 240px)}main{width:min(100%,640px);margin:10px auto;background:#fff;border:1px solid #dfe7f0;border-radius:18px;box-shadow:0 12px 32px #1d4ed80f;padding:clamp(22px,5vw,38px)}.brand{display:flex;align-items:center;gap:8px;color:#2563eb;font-weight:700}.brand i{width:9px;height:9px;border-radius:50%;background:#2563eb}.eyebrow{margin-top:14px;color:#64748b;font-size:13px}h1{font-size:clamp(24px,5vw,31px);margin:8px 0 10px;line-height:1.3}p{color:#64748b;line-height:1.6}.rules{border:1px solid #dbe4ef;border-radius:12px;padding:14px;background:#f8fafc}.rules strong{display:block;margin-bottom:8px;color:#0f172a}.rules ol{margin:0;padding-left:22px;color:#475569;line-height:1.7}form{display:grid;gap:16px;margin-top:20px}label{display:grid;gap:7px;font-weight:650;color:#334155}.label-text{display:flex;align-items:baseline;gap:3px;line-height:1.4}.required{display:inline-block;color:#dc2626;font-weight:750;line-height:1;margin:0}input,textarea{width:100%;border:1px solid #cbd5e1;border-radius:10px;padding:11px 12px;font:inherit;background:#fff;color:#0f172a}textarea{min-height:88px;resize:vertical}input:focus,textarea:focus{outline:0;border-color:#2563eb;box-shadow:0 0 0 3px #2563eb20}.signature{border:1px solid #cbd5e1;border-radius:12px;padding:10px;background:#fbfdff}.signature canvas{display:block;width:100%;height:150px;background:#fff;border:1px dashed #94a3b8;border-radius:8px;touch-action:none}.signature button{margin-top:8px;background:#e2e8f0;color:#334155;box-shadow:none;min-height:36px}.actions{display:grid;gap:10px}button{min-height:48px;border:0;border-radius:10px;background:#2563eb;color:#fff;font:inherit;font-weight:700;cursor:pointer}button:disabled{opacity:.6;cursor:wait}.message{min-height:22px;color:#b42318}.success{color:#15803d}.modal{position:fixed;inset:0;background:#0f172a88;display:grid;place-items:center;padding:20px;z-index:5}.modal[hidden]{display:none}.modal-card{max-width:600px;max-height:90vh;overflow:auto;background:#fff;border-radius:16px;padding:24px}.modal-card button{width:100%;margin-top:16px}@media(max-width:520px){main{margin:0 auto;padding:22px 18px;border-radius:14px}}
</style></head><body><div id="rules" class="modal"><section class="modal-card"><h2>公安部关于严禁违规宴请饮酒的规定</h2><ol><li>严禁在工作日、值班备勤、安保任务、公务出差、学习培训期间和其他工作时间饮酒。</li><li>严禁领导干部之间、单位之间相互宴请。</li><li>严禁接受下属或地方公安机关宴请。</li><li>严禁接受管理和服务对象宴请。</li><li>严禁出入私人会所或参与“一桌餐”。</li><li>严禁在任何时间、任何场合酗酒。</li></ol><button id="rules-close" disabled>请阅读规定（3）</button></section></div><main><div class="brand"><i></i>滨湖新城派出所</div><div class="eyebrow">非工作日事项登记</div><h1>苏州市公安局非工作日饮酒报备单</h1><p>请如实填写报备信息，并由报备人和责任领导在本页完成签名。</p><div class="rules"><strong>报备承诺</strong><span>我承诺本次饮酒不违反中央八项规定及其实施细则精神和公安部“六项规定”。</span></div><form id="form" novalidate><label><span class="label-text">姓名<span class="required" aria-hidden="true">*</span></span><input name="name" maxlength="100" required></label><label><span class="label-text">单位职务<span class="required" aria-hidden="true">*</span></span><input name="unit_position" maxlength="200" required></label><label><span class="label-text">饮酒时间<span class="required" aria-hidden="true">*</span></span><input name="drinking_at" type="datetime-local" required></label><label><span class="label-text">饮酒地点<span class="required" aria-hidden="true">*</span></span><input name="drinking_place" maxlength="500" required></label><label><span class="label-text">饮酒事由<span class="required" aria-hidden="true">*</span></span><input name="reason" maxlength="500" required></label><label><span class="label-text">邀约人<span class="required" aria-hidden="true">*</span></span><input name="inviter" maxlength="100" required></label><label><span class="label-text">出行方式<span class="required" aria-hidden="true">*</span></span><input name="travel_method" maxlength="100" value="自驾、公共交通" required></label><label><span class="label-text">责任领导姓名<span class="required" aria-hidden="true">*</span></span><input name="responsible_leader_name" maxlength="100" required></label><label><span class="label-text">备注说明</span><textarea name="notes" maxlength="2000"></textarea></label><label><span class="label-text">报备人签名<span class="required" aria-hidden="true">*</span></span><div class="signature"><canvas data-signature="reporter"></canvas><button type="button" data-clear="reporter">清除签名</button></div></label><label><span class="label-text">责任领导签名<span class="required" aria-hidden="true">*</span></span><div class="signature"><canvas data-signature="leader"></canvas><button type="button" data-clear="leader">清除签名</button></div></label><div class="actions"><button type="submit">提交报备</button><button type="button" id="show-rules">再次查看规定</button><div id="message" class="message" role="status" aria-live="polite"></div></div></form></main><script>
const token=decodeURIComponent(location.pathname.split('/').pop()||''),form=document.querySelector('#form'),message=document.querySelector('#message'),rules=document.querySelector('#rules'),closeRules=document.querySelector('#rules-close');let formToken='';const uuid=()=>typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0,v=c==='x'?r:r&3|8;return v.toString(16)}),submissionId=uuid(),deviceId=(()=>{const k='binhu_drinking_device';try{let v=localStorage.getItem(k);if(!v){v=uuid()+uuid();localStorage.setItem(k,v)}return v}catch(_){return uuid()+uuid()}})();const state={reporter:[],leader:[]};document.body.style.overflow='hidden';function resize(canvas){const r=canvas.getBoundingClientRect(),d=devicePixelRatio||1;canvas.width=r.width*d;canvas.height=r.height*d;canvas.getContext('2d').scale(d,d)}function setup(canvas,key){resize(canvas);let active=null;const point=e=>{const r=canvas.getBoundingClientRect();return {x:+((e.clientX-r.left)/r.width).toFixed(4),y:+((e.clientY-r.top)/r.height).toFixed(4)}};canvas.onpointerdown=e=>{canvas.setPointerCapture(e.pointerId);active=[point(e)];state[key].push(active)};canvas.onpointermove=e=>{if(!active)return;active.push(point(e));const ctx=canvas.getContext('2d');const r=canvas.getBoundingClientRect();ctx.strokeStyle='#0f172a';ctx.lineWidth=2;ctx.lineCap='round';ctx.beginPath();const p=active[active.length-2],q=active[active.length-1];ctx.moveTo(p.x*r.width,p.y*r.height);ctx.lineTo(q.x*r.width,q.y*r.height);ctx.stroke()};canvas.onpointerup=canvas.onpointercancel=()=>{active=null}}document.querySelectorAll('canvas[data-signature]').forEach(c=>setup(c,c.dataset.signature));document.querySelectorAll('[data-clear]').forEach(b=>b.onclick=()=>{const k=b.dataset.clear;state[k]=[];const c=document.querySelector(`canvas[data-signature="${k}"]`);c.getContext('2d').clearRect(0,0,c.width,c.height)});let seconds=3;const timer=setInterval(()=>{seconds-=1;if(seconds<=0){clearInterval(timer);closeRules.disabled=false;closeRules.textContent='我已阅读并同意';}else closeRules.textContent=`请阅读规定（${seconds}）`},1000);const startRules=()=>{rules.hidden=false;document.body.style.overflow='hidden';closeRules.disabled=true;let remaining=3;closeRules.textContent='请阅读规定（'+remaining+'）';const handle=setInterval(()=>{remaining-=1;if(remaining<=0){clearInterval(handle);closeRules.disabled=false;closeRules.textContent='我已阅读并同意'}else closeRules.textContent='请阅读规定（'+remaining+'）'},1000)};closeRules.onclick=()=>{rules.hidden=true;document.body.style.overflow=''};document.querySelector('#show-rules').onclick=startRules;fetch(`/api/public/forms/${encodeURIComponent(token)}`).then(async r=>{const d=await r.json();if(!r.ok)throw Error(d.detail||'二维码不可用');formToken=d.form_token}).catch(e=>{message.textContent=e.message;form.querySelector('button[type=submit]').disabled=true});form.onsubmit=async e=>{e.preventDefault();if(!form.reportValidity())return;if(!state.reporter.some(s=>s.length>1)||!state.leader.some(s=>s.length>1)){message.textContent='请完成双方签名';return}const values=Object.fromEntries(new FormData(form).entries());const body={submission_id:submissionId,form_token:formToken,form_token_value:token,device_id:deviceId,...values,reporter_signature:state.reporter,leader_signature:state.leader};const btn=form.querySelector('button[type=submit]');btn.disabled=true;message.textContent='正在提交…';try{const r=await fetch('/api/public/drinking-reports',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(d.detail||'提交失败');message.textContent='提交成功，平台已收到报备';message.className='message success';form.querySelectorAll('input,textarea,button').forEach(x=>x.disabled=true)}catch(err){message.textContent=err.message||'提交失败';btn.disabled=false}};
</script></body></html>'''
